import React, { useContext, useEffect, useRef, useState } from "react";
import noteContext from "../context/notes/noteContext";
import { useNavigate } from "react-router-dom";
import Noteitem from "./Noteitem";
import AddNote from "./AddNote";

const Notes = (props) => {
  const context = useContext(noteContext);
  let navigate = useNavigate();
  const { notes, getNotes, editNote } = context;
  
  useEffect(() => {
    const token = localStorage.getItem('token');
    if(token){
      // Check if getNotes exists and is a function
      if (getNotes && typeof getNotes === 'function') {
        getNotes().catch(error => {
          console.error('Error fetching notes:', error);
          props.showAlert("Failed to fetch notes. Please try refreshing the page.", "danger");
        });
      } else {
        console.error('getNotes function not available');
        props.showAlert("Unable to load notes. Please check your connection.", "danger");
      }
    } else {
      navigate("/login");
    }
    // eslint-disable-next-line
  }, []);
  
  const ref = useRef(null);
  const refClose = useRef(null);
  const [note, setNote] = useState({
    id: "",
    etitle: "",
    edescription: "",
    etag: ""
  });
  
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedTag, setSelectedTag] = useState("");
  const [isModalOpen, setIsModalOpen] = useState(false);

  const updateNote = (currentNote) => {
    setNote({
      id: currentNote._id,
      etitle: currentNote.title,
      edescription: currentNote.description,
      etag: currentNote.tag || ""
    });
    setIsModalOpen(true);
  };

  const handleClick = async () => {
    // Validation
    if (note.etitle.length < 5) {
      props.showAlert("Title must be at least 5 characters long", "danger");
      return;
    }
    
    if (note.edescription.length < 5) {
      props.showAlert("Description must be at least 5 characters long", "danger");
      return;
    }

    try {
      if (editNote && typeof editNote === 'function') {
        const success = await editNote(note.id, note.etitle, note.edescription, note.etag);
        if (success) {
          setIsModalOpen(false);
          props.showAlert("Note updated successfully! ✨", "success");
        } else {
          props.showAlert("Failed to update note. Please try again.", "danger");
        }
      } else {
        props.showAlert("Update function not available", "danger");
      }
    } catch (error) {
      console.error('Error updating note:', error);
      props.showAlert("Failed to update note. Please try again.", "danger");
    }
  };
  
  const onChange = (e) => {
    setNote({ ...note, [e.target.name]: e.target.value });
  };

  const closeModal = () => {
    setIsModalOpen(false);
  };

  // Get unique tags from notes
  const getAllTags = () => {
    if (!notes || !Array.isArray(notes)) return [];
    const tags = new Set();
    notes.forEach(note => {
      if (note.tag && note.tag.trim()) {
        tags.add(note.tag.trim());
      }
    });
    return Array.from(tags).sort();
  };

  // Filter notes based on search and tag
  const getFilteredNotes = () => {
    if (!notes || !Array.isArray(notes)) return [];
    return notes.filter(note => {
      const matchesSearch = !searchTerm || 
        note.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        note.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (note.tag && note.tag.toLowerCase().includes(searchTerm.toLowerCase()));
      
      const matchesTag = !selectedTag || note.tag === selectedTag;
      
      return matchesSearch && matchesTag;
    });
  };

  // Ensure notes is an array before processing
  const safeNotes = notes && Array.isArray(notes) ? notes : [];
  const filteredNotes = getFilteredNotes();
  const availableTags = getAllTags();

  const clearFilters = () => {
    setSearchTerm("");
    setSelectedTag("");
  };

  // Handle keyboard events for modal
  useEffect(() => {
    const handleKeyDown = (event) => {
      if (event.key === 'Escape' && isModalOpen) {
        closeModal();
      }
    };

    if (isModalOpen) {
      document.addEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'hidden';
    }

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'unset';
    };
  }, [isModalOpen]);

  return (
    <div className="container-fluid px-3">
      <AddNote showAlert={props.showAlert} />
      
      {/* Search and Filter Section */}
      <div className="card my-4">
        <div className="card-header">
          <h3 className="mb-1">
            <i className="fas fa-search me-2"></i>Find Your Notes
          </h3>
          <p className="text-muted mb-0">Search through your thoughts and ideas</p>
        </div>
        
        <div className="card-body">
          <div className="row g-3">
            {/* Search Input */}
            <div className="col-md-8">
              <div className="position-relative">
                <i className="fas fa-search position-absolute top-50 start-0 translate-middle-y ms-3 text-muted"></i>
                <input
                  type="text"
                  className="form-control ps-5"
                  placeholder="Search by title, content, or tag..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
                {searchTerm && (
                  <button
                    className="btn btn-outline-secondary btn-sm position-absolute top-50 end-0 translate-middle-y me-2"
                    onClick={() => setSearchTerm("")}
                    title="Clear search"
                    aria-label="Clear search"
                  >
                    <i className="fas fa-times"></i>
                  </button>
                )}
              </div>
            </div>

            {/* Tag Filter */}
            <div className="col-md-4">
              <select
                className="form-select"
                value={selectedTag}
                onChange={(e) => setSelectedTag(e.target.value)}
              >
                <option value="">All Tags</option>
                {availableTags.map((tag, index) => (
                  <option key={index} value={tag}>
                    {tag}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* Active Filters Display */}
          {(searchTerm || selectedTag) && (
            <div className="d-flex justify-content-between align-items-center mt-3 pt-3 border-top">
              <div>
                <small className="text-muted me-2">Active filters:</small>
                {searchTerm && (
                  <span className="badge bg-primary me-2">
                    <i className="fas fa-search me-1"></i>
                    "{searchTerm}"
                  </span>
                )}
                {selectedTag && (
                  <span className="badge bg-info">
                    <i className="fas fa-tag me-1"></i>
                    {selectedTag}
                  </span>
                )}
              </div>
              <button
                className="btn btn-outline-secondary btn-sm"
                onClick={clearFilters}
              >
                <i className="fas fa-times me-1"></i>Clear All
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Notes Statistics */}
      <div className="row mb-4">
        <div className="col-md-3 col-sm-6 mb-3">
          <div className="card text-center h-100">
            <div className="card-body">
              <i className="fas fa-sticky-note text-primary fs-2 mb-2"></i>
              <h4 className="mb-1">{safeNotes.length}</h4>
              <small className="text-muted">Total Notes</small>
            </div>
          </div>
        </div>
        
        <div className="col-md-3 col-sm-6 mb-3">
          <div className="card text-center h-100">
            <div className="card-body">
              <i className="fas fa-filter text-success fs-2 mb-2"></i>
              <h4 className="mb-1">{filteredNotes.length}</h4>
              <small className="text-muted">Showing</small>
            </div>
          </div>
        </div>
        
        <div className="col-md-3 col-sm-6 mb-3">
          <div className="card text-center h-100">
            <div className="card-body">
              <i className="fas fa-tags text-info fs-2 mb-2"></i>
              <h4 className="mb-1">{availableTags.length}</h4>
              <small className="text-muted">Unique Tags</small>
            </div>
          </div>
        </div>
        
        <div className="col-md-3 col-sm-6 mb-3">
          <div className="card text-center h-100">
            <div className="card-body">
              <i className="fas fa-font text-warning fs-2 mb-2"></i>
              <h4 className="mb-1">
                {Math.round(safeNotes.reduce((total, note) => total + (note.description?.length || 0), 0) / 1000)}k
              </h4>
              <small className="text-muted">Characters</small>
            </div>
          </div>
        </div>
      </div>

      {/* Notes Display */}
      <div className="notes-section">
        <div className="d-flex justify-content-between align-items-center mb-4">
          <h2 className="mb-0">
            <i className="fas fa-book-open me-2"></i>
            Your Digital Journal
          </h2>
          <div className="text-muted">
            {filteredNotes.length === safeNotes.length ? (
              <span>{safeNotes.length} {safeNotes.length === 1 ? 'note' : 'notes'}</span>
            ) : (
              <span>
                Showing {filteredNotes.length} of {safeNotes.length} {safeNotes.length === 1 ? 'note' : 'notes'}
              </span>
            )}
          </div>
        </div>
        
        <div className="row">
          {filteredNotes.length === 0 && safeNotes.length === 0 && (
            <div className="col-12">
              <div className="text-center py-5">
                <i className="fas fa-book-open text-muted" style={{fontSize: '4rem'}}></i>
                <h3 className="mt-3">Your journal awaits</h3>
                <p className="text-muted">Start documenting your thoughts, ideas, and experiences. Create your first note above!</p>
                <div className="row justify-content-center mt-4">
                  <div className="col-auto">
                    <div className="d-flex align-items-center">
                      <i className="fas fa-shield-alt text-success me-2"></i>
                      <span>Secure & Private</span>
                    </div>
                  </div>
                  <div className="col-auto">
                    <div className="d-flex align-items-center">
                      <i className="fas fa-sync text-primary me-2"></i>
                      <span>Auto-saved</span>
                    </div>
                  </div>
                  <div className="col-auto">
                    <div className="d-flex align-items-center">
                      <i className="fas fa-search text-info me-2"></i>
                      <span>Searchable</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}
          
          {filteredNotes.length === 0 && safeNotes.length > 0 && (
            <div className="col-12">
              <div className="text-center py-5">
                <i className="fas fa-search text-muted" style={{fontSize: '4rem'}}></i>
                <h3 className="mt-3">No notes match your search</h3>
                <p className="text-muted">Try adjusting your search terms or clearing filters to see more results.</p>
                <button className="btn btn-outline-primary" onClick={clearFilters}>
                  <i className="fas fa-times me-2"></i>Clear Filters
                </button>
              </div>
            </div>
          )}
          
          {filteredNotes.map((note) => (
            <Noteitem
              key={note._id}
              updateNote={updateNote}
              note={note}
              showAlert={props.showAlert}
            />
          ))}
        </div>
      </div>

      {/* Edit Note Modal */}
      {isModalOpen && (
        <div 
          className="modal d-block" 
          style={{backgroundColor: 'rgba(0,0,0,0.5)', zIndex: 1050}} 
          onClick={closeModal}
        >
          <div className="modal-dialog modal-lg" onClick={(e) => e.stopPropagation()}>
            <div className="modal-content">
              <div className="modal-header">
                <h5 className="modal-title">
                  <i className="fas fa-edit me-2"></i>Edit Note
                </h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={closeModal}
                  aria-label="Close"
                ></button>
              </div>
              
              <div className="modal-body">
                <form>
                  <div className="mb-3">
                    <label htmlFor="etitle" className="form-label">
                      <i className="fas fa-heading me-2"></i>Title
                    </label>
                    <input
                      type="text"
                      className="form-control"
                      id="etitle"
                      name="etitle"
                      value={note.etitle}
                      onChange={onChange}
                      required
                    />
                    <div className="form-text">
                      <span className={note.etitle.length >= 5 ? 'text-success' : 'text-danger'}>
                        {note.etitle.length}/∞ characters {note.etitle.length >= 5 ? '✓' : '(minimum 5)'}
                      </span>
                    </div>
                  </div>
                  
                  <div className="mb-3">
                    <label htmlFor="edescription" className="form-label">
                      <i className="fas fa-align-left me-2"></i>Content
                    </label>
                    <textarea
                      className="form-control"
                      id="edescription"
                      name="edescription"
                      value={note.edescription}
                      onChange={onChange}
                      rows="8"
                      required
                    />
                    <div className="form-text">
                      <span className={note.edescription.length >= 5 ? 'text-success' : 'text-danger'}>
                        {note.edescription.length} characters {note.edescription.length >= 5 ? '✓' : '(minimum 5)'}
                      </span>
                    </div>
                  </div>
                  
                  <div className="mb-3">
                    <label htmlFor="etag" className="form-label">
                      <i className="fas fa-tag me-2"></i>Tag (Optional)
                    </label>
                    <input
                      type="text"
                      className="form-control"
                      id="etag"
                      name="etag"
                      value={note.etag}
                      onChange={onChange}
                      placeholder="Enter a tag to categorize your note"
                    />
                  </div>
                </form>
              </div>
              
              <div className="modal-footer">
                <button
                  type="button"
                  className="btn btn-secondary"
                  onClick={closeModal}
                >
                  <i className="fas fa-times me-2"></i>Cancel
                </button>
                <button
                  type="button"
                  className="btn btn-primary"
                  onClick={handleClick}
                  disabled={note.etitle.length < 5 || note.edescription.length < 5}
                >
                  <i className="fas fa-save me-2"></i>Update Note
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Notes;
